let leagueCentreRound=null,leagueCentreClub='all',leagueCentreReturn=null;
const leagueResultNames={win:'승',draw:'무',loss:'패'},leagueMatchNames={confirmed:'결과 확정',pending:'종료 · 결과 미확정',next:'이번 리그 경기',scheduled:'예정'};
function leagueFormMarkup(form){return form.length?'<span class="league-form">'+form.map(g=>'<span class="'+g.outcome+'" title="'+g.round+'R '+escapeText(g.opponent.short)+' '+g.goals.join(':')+'" aria-label="'+g.round+'라운드 '+escapeText(g.opponent.short)+' '+g.goals.join(' 대 ')+' '+leagueResultNames[g.outcome]+'">'+leagueResultNames[g.outcome]+'</span>').join('')+'</span>':'<span class="league-no-form">기록 없음</span>';}
function renderLeagueCentre(){
 const dialog=$('league-centre-dialog');if(!dialog?.open)return;const m=LeagueCentre.read(season,{round:leagueCentreRound,clubId:leagueCentreClub}),esc=escapeText,ownClub=S.club(S.own);leagueCentreRound=m.selectedRound;leagueCentreClub=m.clubId;
 const r=m.race,status=!r.rank?'첫 결과 대기':r.final?'최종 '+r.rank+'위':'현재 '+r.rank+'위',selected=m.selected;
 dialog.innerHTML='<header class="league-centre-head"><div><span class="eyebrow">리그 현황 / '+m.year+' 시즌</span><h2 id="league-centre-title">'+esc(m.league)+' · 순위와 전 경기</h2></div><button type="button" class="secondary" id="close-league-centre" aria-label="리그 센터 닫기">×</button></header><div class="league-centre-body"><p class="league-centre-note">'+esc(m.note)+'</p><div class="league-centre-filters"><label>리그 라운드<select id="league-centre-round">'+Array.from({length:m.rounds},(_,i)=>'<option value="'+(i+1)+'"'+(i+1===m.selectedRound?' selected':'')+'>'+(i+1)+'R'+' · '+m.roundStates[i]+'</option>').join('')+'</select></label><label>구단별 경기<select id="league-centre-club"><option value="all">전체 구단</option>'+m.clubs.map(c=>'<option value="'+esc(c.id)+'"'+(m.clubId===c.id?' selected':'')+'>'+esc(c.short)+'</option>').join('')+'</select></label></div><div class="league-round-nav"><button type="button" id="league-round-prev" class="secondary" '+(m.selectedRound===1?'disabled':'')+'>← 이전 라운드</button><strong>'+m.selectedRound+'R · '+m.matches.length+'경기</strong><button type="button" id="league-round-next" class="secondary" '+(m.selectedRound===m.rounds?'disabled':'')+'>다음 라운드 →</button></div><ul class="league-centre-games">'+m.matches.map(g=>'<li class="'+(g.ourGame?'our-game':'')+'"><div class="league-fixture-status">'+(g.status==='live'?g.minute+'분 · 미확정':leagueMatchNames[g.status])+(g.ourGame?' · 우리 구단':'')+'</div><div class="league-fixture-score"><strong>'+esc(g.home.short)+'<small>홈</small></strong><b>'+ (g.score?g.score[0]+' : '+g.score[1]:'대')+'</b><strong>'+esc(g.away.short)+'<small>원정</small></strong></div>'+(g.recordId?'<button type="button" class="secondary" data-league-record="'+esc(g.recordId)+'">우리 경기 상세 기록</button>':g.active?'<button type="button" id="league-current-match" class="secondary">'+(g.status==='pending'?'결과 확정하러 가기':'이번 경기로 이동')+'</button>':'')+'</li>').join('')+'</ul><p class="league-centre-note">다른 구단의 해당 라운드 결과는 우리 리그 경기 결과를 확정할 때 공개됩니다. 순위를 미리 계산하지 않습니다.</p><div class="league-race"><div><span>'+esc(ownClub.name)+' · '+(m.throughRound?m.throughRound+'R까지':'첫 리그 결과 확정 전')+'</span><strong>'+status+' · '+r.points+'점</strong></div><p>'+r.label+' '+r.boundaryRank+'위 '+r.boundaryPoints+'점 · 승점 차 '+(r.gap>0?'+':'')+r.gap+'<small>'+(r.final?'리그 최종 순위입니다.':'동률은 득실차·득점·구단명 순입니다. 승점 차만으로 진출이나 잔류가 확정되지 않습니다.')+'</small></p></div><h3>'+(m.throughRound?m.throughRound+'R까지 확정 순위':'리그 참가 구단 · 첫 결과 대기')+'</h3><div class="league-centre-table" role="region" aria-label="리그 전체 순위, 가로 스크롤 가능" tabindex="0"><table><caption>구단 이름을 눌러 해당 구단의 경기와 최근 흐름을 봅니다. 최근 5경기는 왼쪽에서 오른쪽 순서입니다.</caption><thead><tr><th>순위</th><th>구단</th><th>경기</th><th>승</th><th>무</th><th>패</th><th>득실</th><th>승점</th><th>최근 5경기</th></tr></thead><tbody>'+m.table.map(c=>'<tr class="'+(c.own?'league-own ':'')+(m.clubId===c.id?'league-selected':'')+'"><td>'+(m.throughRound?c.rank:'—')+'<small>'+(c.change===null?'':c.change>0?'↑'+c.change:c.change<0?'↓'+(-c.change):'—')+'</small></td><th scope="row"><button type="button" data-league-club="'+esc(c.id)+'" aria-pressed="'+(m.clubId===c.id)+'">'+esc(c.short)+'</button><small>'+({promotion:'승격권',relegation:'강등권',leader:'선두'}[c.zone]||'')+'</small></th><td>'+c.played+'</td><td>'+c.won+'</td><td>'+c.drawn+'</td><td>'+c.lost+'</td><td>'+(c.gd>0?'+':'')+c.gd+'</td><td><b>'+c.points+'</b></td><td>'+leagueFormMarkup(c.form)+'</td></tr>').join('')+'</tbody></table></div>'+(selected?'<section class="league-club-form" aria-label="선택 구단 최근 리그 경기"><h3>'+esc(selected.name)+' · 최근 리그 경기</h3>'+(selected.form.length?'<ol>'+selected.form.map(g=>'<li><b class="'+g.outcome+'">'+leagueResultNames[g.outcome]+'</b><span>'+g.round+'R · '+(g.home?'홈':'원정')+' · '+esc(g.opponent.short)+'</span><strong>'+g.goals[0]+' : '+g.goals[1]+'</strong></li>').join('')+'</ol>':'<p>선택한 시점까지 확정된 리그 경기가 없습니다.</p>')+'</section>':'')+'<p class="league-centre-note">현재 시즌의 순위와 대진입니다. 지난 시즌의 우리 선수·경기 기록은 시즌 기록과 통산 기록에서 확인하세요.</p></div>';
 const close=()=>{dialog.close();leagueCentreReturn?.focus?.({preventScroll:true});},redraw=id=>{renderLeagueCentre();$(id)?.focus({preventScroll:true});};$('close-league-centre').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};
 $('league-centre-round').onchange=e=>{leagueCentreRound=Number(e.target.value);redraw('league-centre-round');};$('league-centre-club').onchange=e=>{leagueCentreClub=e.target.value;redraw('league-centre-club');};
 $('league-round-prev').onclick=()=>{if(m.selectedRound>1){leagueCentreRound=m.selectedRound-1;redraw('league-centre-round');}};$('league-round-next').onclick=()=>{if(m.selectedRound<m.rounds){leagueCentreRound=m.selectedRound+1;redraw('league-centre-round');}};
 dialog.querySelectorAll('[data-league-club]').forEach(b=>b.onclick=()=>{leagueCentreClub=b.dataset.leagueClub;renderLeagueCentre();$('league-centre-club').scrollIntoView({block:'nearest',behavior:'instant'});$('league-centre-club').focus({preventScroll:true});});dialog.querySelectorAll('[data-league-record]').forEach(b=>b.onclick=()=>openMatchArchive(b.dataset.leagueRecord));
 const current=$('league-current-match');if(current)current.onclick=()=>{dialog.close();setView('match');$('primary')?.focus({preventScroll:true});};
}
function openLeagueCentre(){const dialog=$('league-centre-dialog');if(!dialog)return;pauseForPlanning();leagueCentreRound=null;leagueCentreClub='all';leagueCentreReturn=document.activeElement;if(!dialog.open)dialog.showModal();renderLeagueCentre();dialog.scrollTop=0;$('close-league-centre').focus({preventScroll:true});}
document.addEventListener('click',event=>{if(event.target.closest('[data-open-league]'))openLeagueCentre();});
